mapper.select:
SELECT DISTINCT m.item_code as `key`, m.item_value as `value` FROM ( SELECT t.`owner_id` AS userName, t.`module_code`, t.`dim_code`, t.`item_code`, t.`item_value` FROM bi_portal.sys_data_auth t WHERE t.`owner_type` = 'User' AND t.`module_code` = #{moduleCode} AND t.owner_id = #{userName} AND t.created_time > DATE_ADD(CURDATE(), INTERVAL -1* t.active_duration_days DAY)
AND t.`dim_code` = #{dimCode}
UNION ALL SELECT sur.USER_NAME AS userName, t1.`module_code`, t1.`dim_code`, t1.`item_code`, t1.`item_value` FROM bi_portal.sys_data_auth t1 INNER JOIN bi_portal.sys_user_role sur ON t1.`owner_id` = sur.ROLE_ID WHERE t1.`owner_type` = 'Role' AND t1.`module_code` = #{moduleCode} AND sur.USER_NAME = #{userName}
AND t1.`dim_code` = #{dimCode}
AND sur.created_time > DATE_ADD(CURDATE(), INTERVAL -1* sur.active_duration_days DAY)
UNION ALL
SELECT '${userName}' as userName, t1.`module_code`, t1.`dim_code`, t1.`item_code`, t1.`item_value` FROM bi_portal.sys_data_auth t1 WHERE t1.owner_type= 'Dept' AND t1.`module_code` = #{moduleCode}
AND t1.`dim_code` = #{dimCode}
AND CONCAT(#{deptId}, '/') LIKE CONCAT('%', t1.owner_id, '/%') AND t1.created_time > DATE_ADD(CURDATE(), INTERVAL -1* t1.active_duration_days DAY) ) m ORDER BY m.item_code

SELECT m.item_code as ctgId, MAX(m.authEndDate) as authEndDate FROM ( SELECT t.`item_code`, DATE_FORMAT(DATE_ADD(t.created_time, INTERVAL t.active_duration_days DAY), '%Y-%m-%d') as authEndDate FROM bi_portal.sys_data_auth t WHERE t.`owner_type` = 'User' AND t.`module_code` = #{moduleCode} AND t.owner_id = #{userName} AND t.created_time > DATE_ADD(CURDATE(), INTERVAL -1* t.active_duration_days DAY)
AND t.`dim_code` = #{dimCode}
UNION ALL SELECT t1.`item_code`, DATE_FORMAT(DATE_ADD(t1.created_time, INTERVAL t1.active_duration_days DAY), '%Y-%m-%d') as authEndDate FROM bi_portal.sys_data_auth t1 INNER JOIN bi_portal.sys_user_role sur ON t1.`owner_id` = sur.ROLE_ID WHERE t1.`owner_type` = 'Role' AND t1.`module_code` = #{moduleCode} AND sur.USER_NAME = #{userName}
AND t1.`dim_code` = #{dimCode}
AND sur.created_time > DATE_ADD(CURDATE(), INTERVAL -1* sur.active_duration_days DAY)
UNION ALL
SELECT t1.`item_code`, DATE_FORMAT(DATE_ADD(t1.created_time, INTERVAL t1.active_duration_days DAY), '%Y-%m-%d') as authEndDate FROM bi_portal.sys_data_auth t1 WHERE t1.owner_type= 'Dept' AND t1.`module_code` = #{moduleCode}
AND t1.`dim_code` = #{dimCode}
AND CONCAT(#{deptId}, '/') LIKE CONCAT('%', t1.owner_id, '/%') AND t1.created_time > DATE_ADD(CURDATE(), INTERVAL -1* t1.active_duration_days DAY) ) m GROUP BY m.item_code ORDER BY m.item_code

